/* udis86 - docs/frame_example.c
 *
 * Example: run ud_frame_analyze() over a caller-recovered basic block
 * graph and print the per-instruction frame state and stack accesses.
 *
 * Build (from the repository root):
 *   cc -std=c99 -DHAVE_STRING_H=1 -I. -Ilibudis86 libudis86/frame.c \
 *      libudis86/decode.c libudis86/udis86.c libudis86/syn.c \
 *      libudis86/syn-att.c libudis86/syn-intel.c libudis86/itab.c \
 *      docs/frame_example.c -o frame_example
 * (itab.c is generated by the normal build; see task_support/build.sh for
 * a self-contained compile line.)
 */
#include <stdio.h>
#include <string.h>

#include "udis86.h"
#include "libudis86/frame.h"

static void
print_value(const char *name, struct ud_frame_value v)
{
  printf("%s=", name);
  switch (v.kind) {
  case UD_FRAME_VALUE_OFFSET:
    printf("S%+lld", (long long) v.offset);
    break;
  case UD_FRAME_VALUE_UNKNOWN:
    printf("?");
    break;
  default:
    printf("<unreached>");
    break;
  }
}

int
main(void)
{
  /* push rbp; mov rbp,rsp; sub rsp,0x20; mov [rbp-8],rax;
     call .+0; leave; ret */
  static const unsigned char code[] = {
    0x55,                         /* 0: push rbp           */
    0x48, 0x89, 0xe5,             /* 1: mov rbp, rsp       */
    0x48, 0x83, 0xec, 0x20,       /* 4: sub rsp, 0x20      */
    0x48, 0x89, 0x45, 0xf8,       /* 8: mov [rbp-8], rax   */
    0xe8, 0x00, 0x00, 0x00, 0x00, /* 12: call next         */
    0xc9,                         /* 17: leave             */
    0xc3                          /* 18: ret               */
  };
  static const size_t fallthrough[] = { 1 };
  static const struct ud_frame_block_desc blocks[] = {
    { 0, 17, fallthrough, 1 },  /* block 0: prologue + call */
    { 17, 19, NULL, 0 },        /* block 1: leave; ret      */
  };
  struct ud_frame_graph graph;
  struct ud_frame_report *report = NULL;
  struct ud_frame_error error;
  enum ud_frame_status st;
  size_t i, j, k;

  memset(&graph, 0, sizeof(graph));
  graph.code = code;
  graph.code_size = sizeof(code);
  graph.entry = 0;
  graph.blocks = blocks;
  graph.block_count = sizeof(blocks) / sizeof(blocks[0]);

  st = ud_frame_analyze(&graph, &report, &error);
  if (st != UD_FRAME_OK) {
    fprintf(stderr, "analysis failed: status=%d block=%zu offset=%llu\n",
            (int) st,
            error.block == UD_FRAME_NO_BLOCK ? -1 : (ptrdiff_t) error.block,
            (unsigned long long) error.offset);
    return 1;
  }

  for (i = 0; i < report->block_count; ++i) {
    const struct ud_frame_block *b = &report->blocks[i];
    printf("block #%zu [%llu, %llu):\n", b->index,
           (unsigned long long) b->begin, (unsigned long long) b->end);
    for (j = 0; j < b->insn_count; ++j) {
      const struct ud_frame_insn *in = &b->insns[j];
      printf("  +%llu: ", (unsigned long long) in->offset);
      print_value("rsp", in->rsp);
      printf(" ");
      print_value("rbp", in->rbp);
      for (k = 0; k < in->access_count; ++k) {
        const struct ud_frame_access *a = &in->accesses[k];
        printf("  [%s %u bits ",
               a->kind == UD_FRAME_ACCESS_READ ? "read" :
               a->kind == UD_FRAME_ACCESS_WRITE ? "write" : "addr",
               a->size);
        print_value("at", a->address);
        printf("]");
      }
      printf("\n");
    }
  }

  ud_frame_report_free(report);
  return 0;
}
